--
-- Name: guid32(); Type: FUNCTION; Schema: e3000__comm; Owner: postgres
--

CREATE FUNCTION e3000__comm.guid32() RETURNS text
    LANGUAGE plpgsql
    AS $$declare 
  cGuid Text;
begin
  cGuid :=replace(cast(gen_random_uuid() as Text),'-','');
  Return cGuid; 
end $$;


ALTER FUNCTION e3000__comm.guid32() OWNER TO postgres;

--
-- Name: 沖碼更新(text, text, text); Type: PROCEDURE; Schema: e3000__comm; Owner: postgres
--

CREATE PROCEDURE e3000__comm."沖碼更新"(IN ctable1 text, IN cwhere text, IN cupdatefieldlist text)
    LANGUAGE plpgsql
    AS $_$
declare
	cSQL text;
begin
    cSQL=Format('Update %I Set %s where %s ',$1,$3,$2);
	
	--raise notice '%',cSQL;
	
	execute cSQL;
	
end; $_$;


ALTER PROCEDURE e3000__comm."沖碼更新"(IN ctable1 text, IN cwhere text, IN cupdatefieldlist text) OWNER TO postgres;

--
-- Name: 結構同步(text, text); Type: PROCEDURE; Schema: e3000__comm; Owner: postgres
--

CREATE PROCEDURE e3000__comm."結構同步"(IN ctable1 text, IN cschema text)
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2021/12/15 例如: select 資料結構同步('std','targe','public') */
    oRec record;
    /* 缺少之欄位 */
    t1 cursor for select aa.* from 資料結構($3,$1) aa  where aa.field_name not in (select bb.field_name from 資料結構($3,$2) bb );
    /* 相異之欄位  */
    t2 cursor for select aa.* from 資料結構($3,$1) aa,資料結構($3,$2) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    cSQL text;
begin
    --1.遇缺則補
    for oRec in t1 Loop    
        if  Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s add column %s %s(%s,%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
            --有長度數字
            cSQL = format('alter table %s add column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
            --有長度文字
            cSQL = format('alter Table %s add column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
