--
-- Name: 資料結構差異數(text, text, text); Type: FUNCTION; Schema: e3000__comm; Owner: postgres
--

CREATE FUNCTION e3000__comm."資料結構差異數"(ctable1 text, ctable2 text, cschema text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$declare
	nCount integer;
begin 
	-- t1=>source t2=>targe
	select count(1) from 資料結構($3,$1) t1 
		left join 資料結構($3,$2) t2 on (
			t1.field_name = t2.field_name and t1.field_type = t2.field_type and t1.field_len  = t2.field_len  and 
			t1.field_dec  = t2.field_dec  and t1.field_maxlen=t2.field_maxlen) 
		where t2.* is null 
		into nCount;
	
	return nCount;
end; 
$_$;


