--

CREATE FUNCTION e3000__std."資料結構同步"(ctable1 text, ctable2 text, cschema text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2021/12/15 例如: select 資料結構同步('std','targe','public') */
    oRec record;
    /* 缺少之欄位 */--從e3000__std的table同步結構到其他的schema底下的table表
    t1 cursor for select aa.* from 資料結構('e3000__std',$1) aa  where aa.field_name not in (select bb.field_name from 資料結構($3,$2) bb );
    /* 相異之欄位  */--從e3000__std的table同步結構到其他的schema底下的table表
    t2 cursor for select aa.* from 資料結構('e3000__std',$1) aa,資料結構($3,$2) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    cSQL text;
begin
    --1.遇缺則補
    for oRec in t1 Loop    
        if  Not oRec.field_dec = 0 then
        /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有小數
            cSQL = format('alter table %s."%s" add column %s %s(%s,%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
        /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有長度數字
            cSQL = format('alter table %s."%s" add column %s %s(%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
        /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有長度文字
            cSQL = format('alter Table %s."%s" add column %s %s(%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
        /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--只有型態
            cSQL = format('alter Table %s."$s" add column %s %s',$3,$2,oRec.field_name,oRec.field_type) ;
        end if ;   
        
        --預設值設定--/*如果欄位型態為以下則預設為非空值，以「''」當作空值*/
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        --預設值設定--/*如果欄位型態為以下則預設為非空值，以「0」當作空值*/
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='smallint' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行SQL指令       
        execute cSQL;
        
   end loop ;
   
    --2.相異則改  
    for oRec in t2 loop
        if Not oRec.field_dec = 0 then
            /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有小數
            cSQL = format('alter table %s."%s" alter column %s type %s(%s,%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	                        
        elsif Not oRec.field_len = 0 then
            /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有長度
            cSQL = format('alter Table %s."%s" alter column %s type %s(%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_len) ;
        elsif Not oRec.field_maxlen = 0 then
            /*格式化「檢查其他的schema的欄位是否跟e3000__std的欄位是否同步，若沒有則依照e3000__std的欄位進行同步」*/--有長度
            cSQL = format('alter Table %s."%s" alter column %s type %s(%s)',$3,$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;            
        else     
