--
-- Name: isdebit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.isdebit("cAccno" text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$ 
DECLARE 
  Arr0 text[]=ARRAY['1','5','6','8', '9']; -- 第一碼直接判斷 
  Arr1 text[]=ARRAY['1122','1124','1126','1137','1159','1302']; --備抵呆帳及減損科目:1122、1124、1126、1137、1159、1302) 
  Arr2 text[]=ARRAY['1422','1432','1442','1452','1462','1492','1511','1542','1552','1711']; --累折科目(1422、1432、1442、1452、1462、1492、1511、1542、1552、1711) 
  Arr3 text[]=ARRAY['1433','1443','1453','1463','1493','1512','1553','1631','1641','1712']; -- 累計減損(1433、1443、1453、1463、1493、1512、1553、1631、1641、1712) 
  Arr4 text[]=ARRAY['3600']; -- 減:庫藏股票(3600) 
  Arr5 text[]=ARRAY['4201','4202']; -- 銷貨退回折讓(4201、4202) 
  Arr6 text[]=ARRAY['5022','5023','5122','5123','5222','5223']; -- 進貨退出折讓(5022、5023、5122、5123、5222、5223) 
  Arr7 text[]=ARRAY['5050','5150','5250','5554','5564','5566']; -- 減項(5050、5150、5250、5554、5564、5566) 
begin 
 
  if left($1, 4) = Any(Arr1) then --備抵呆帳及減損科目:1122、1124、1126、1137、1159、1302) 
    return false; 
  elsif left($1, 4) = Any(Arr2) then --累折科目(1422、1432、1442、1452、1462、1492、1511、1542、1552、1711) 
    return False; 
  elsif left($1, 4) = Any(Arr3) then -- 累計減損(1433、1443、1453、1463、1493、1512、1553、1631、1641、1712) 
    return False; 
  elsif left($1, 4) = Any(Arr4) then -- 減:庫藏股票(3600) 
    return False; 
  elsif left($1, 4) = Any(Arr5) then  -- 銷貨退回折讓(4201、4202) 
    return False; 
  elsif left($1, 4) = Any(Arr6) then -- 進貨退出折讓(5022、5023、5122、5123、5222、5223) 
    return False; 
  elsif left($1, 4) = Any(Arr7) then -- 減項(5050、5150、5250、5554、5564、5566) 
    return False; 
  elsif left($1, 1) = Any(Arr0) then -- 第一碼直接判斷 
    return True; 
  else 
    return False; 
  end if; 
 
end; 
$_$;


ALTER FUNCTION public.isdebit("cAccno" text) OWNER TO postgres;

--
-- Name: roc_to_ad(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.roc_to_ad(roc_str text) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    parts text[];
    ad_year int;
BEGIN
    -- 支援 / 或 - 或 . 作為分隔符
    parts := regexp_split_to_array(roc_str, '[/\-\.]');    
    -- 民國年轉西元年
    ad_year := parts[1]::int + 1911;    
    -- 組回西元格式並轉為日期
    RETURN to_date(ad_year || '-' || parts[2] || '-' || parts[3], 'YYYY-MM-DD');
EXCEPTION WHEN others THEN
    RETURN NULL; -- 若格式錯誤則回傳空值
END;
$$;


ALTER FUNCTION public.roc_to_ad(roc_str text) OWNER TO postgres;

