--
-- Name: smart_to_date(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.smart_to_date(input_str text) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- 1. 清除所有非數字字元 (例如 / . - 空格)
    clean_num text := regexp_replace(input_str, '\D', '', 'g'); 
    ad_year int;
    mm int;
    dd int;
BEGIN
    -- 情況 A：8 位數字，視為西元 (如 20260203)
    IF length(clean_num) = 8 AND left(clean_num, 2) IN ('19', '20') THEN
        RETURN to_date(clean_num, 'YYYYMMDD');

    -- 情況 B：6 或 7 位數字，視為民國 (如 1150203 或 991231)
    ELSIF length(clean_num) BETWEEN 6 AND 7 THEN
        dd := right(clean_num, 2)::int;          -- 最後 2 位是日
        mm := substring(clean_num, length(clean_num)-3, 2)::int; -- 中間 2 位是月
        ad_year := left(clean_num, length(clean_num)-4)::int + 1911; -- 前面剩下的是年
        
        -- 驗證日期合法性，不合法會跳到 EXCEPTION
        RETURN to_date(ad_year || '-' || mm || '-' || dd, 'YYYY-MM-DD');

    -- 情況 C：帶有分隔符的標準格式 (如 2026/02/03)
    ELSE
        RETURN input_str::date;
    END IF;

EXCEPTION WHEN others THEN
    RETURN NULL; -- 格式全錯或日期不存在（如 2/30）則回傳空值
END;
$$;


ALTER FUNCTION public.smart_to_date(input_str text) OWNER TO postgres;

--
-- Name: to_roc_date(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.to_roc_date(input_date date) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (EXTRACT(YEAR FROM input_date) - 1911) || to_char(input_date, '/MM/DD') ;
END;
$$;


ALTER FUNCTION public.to_roc_date(input_date date) OWNER TO postgres;

