--

CREATE FUNCTION public.zerodiv(namt numeric, nqty numeric, ndec integer DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
begin
	if nQty=0 then 
		Return 0;
	else 
		Return round( (nAmt / nQty) , nDec );
	end if;
end; 
$$;


