--

CREATE PROCEDURE public."修正產品名稱"(IN cschema text)
    LANGUAGE plpgsql
    AS $_$
declare 
  oRec record;
begin
  for oRec in Execute 'select Count(*) as Count from pg_tables where schemaname=$1 and tablename=$2 '  Using 'e3000__data__fred__111','總帳組合配方' Loop    		  
    if oRec.Count = 1 then
      EXECUTE FORMAT('UPDATE %s."總帳組合配方" bb SET "品名"=aa."品名"                ,"單位"=aa."單位" FROM %s."總帳專案產品" aa WHERE aa."品號" = bb."品號"',cSchema,cSchema);      
    end if;	
  end loop ;
  for oRec in Execute 'select Count(*) as Count from pg_tables where schemaname=$1 and tablename=$2 '  Using 'e3000__data__fred__111','總帳部門產品' Loop    		  
    if oRec.Count = 1 then
      EXECUTE FORMAT('UPDATE %s."總帳部門產品" bb SET "品名"=aa."品名","類別"=aa."類別","單位"=aa."單位" FROM %s."總帳專案產品" aa WHERE aa."品號" = bb."品號"',cSchema,cSchema);
    end if;	
  end loop ;
  for oRec in Execute 'select Count(*) as Count from pg_tables where schemaname=$1 and tablename=$2 '  Using 'e3000__data__fred__111','總帳專案產品' Loop    		  
    if oRec.Count = 1 then
      EXECUTE FORMAT('UPDATE %s."總帳專案產品" bb SET "品名"=aa."品名","類別"=aa."類別","單位"=aa."單位" FROM %s."總帳專案產品" aa WHERE aa."品號" = bb."品號"',cSchema,cSchema);    
    end if;	
  end loop ;  
end; 
$_$;


ALTER PROCEDURE public."修正產品名稱"(IN cschema text) OWNER TO postgres;

--
-- Name: 回存常用分錄X_作廢_改到waccin290直接執行(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."回存常用分錄X_作廢_改到waccin290直接執行"()
    LANGUAGE plpgsql
    AS $$
declare
    cGuidOld text default '2AFE4935C86F4D02833819CEDAE27F61';
	cGuidNew text default guid32();
	cur1 cursor for select * from e3000__data__fred__111."總帳傳票表頭" where guid1=cGuidOld; 
	cur2 cursor for select * from e3000__data__fred__111."總帳傳票表身" where guid1=cGuidOld order by "序" ; 	
	r1 record;
	r2 record;    
    cNewNo text;
	
begin
    -- 刪除 00004
	delete from e3000__data__fred__111."總帳常用分錄表頭" where "編號"='00004';
	delete from e3000__data__fred__111."總帳常用分錄表身" where "編號"='00004';
    -- 新編號
    select Max(coalesce("編號",'00000')) from e3000__data__fred__111."總帳常用分錄表頭" into cNewNo;
	SELECT LPAD( Cast((CAST(cNewNo AS integer)+1) as text) ,5,'0') into cNewNo ;	    
	--加入
	for r1 in cur1 loop	
		  Values(cNewNo,r1."類別",'',r1."借方合計",r1."貸方合計",cGuidNew);	
	end loop;
	for r2 in cur2 loop
		  Values(cNewNo,r2."序",r2."項目代號",r2."項目明細",r2."項目名稱",r2."摘要",r2."借方金額",r2."貸方金額",r2."稅額",cGuidNew, guid32(),r2."部門");	
	end loop;
end;
$$;


ALTER PROCEDURE public."回存常用分錄X_作廢_改到waccin290直接執行"() OWNER TO postgres;

--
-- Name: 產品單筆計算(text, text, text, double precision); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."產品單筆計算"(IN cschema text, IN ctable text, IN cprno text, IN ndec double precision)
    LANGUAGE plpgsql
    AS $_$
declare        
    curProduct cursor for select * from e3000__data__fred__111."總帳產品" where "品號"=cPrno;   
	oRec record;    
    cSQL text;
	n異動數量 float;
	n期末數量 float;
	n單位成本 float;
	n期末金額 float;
	n銷貨成本 float;
	
	n異動金額2 float;
	n異動數量2 float;	
begin
	-- 0.假設銷貨及異動已經過帳到產品檔        
    for oRec in curProduct Loop    
	
		-- 1.期末數量 =(進產銷異動加加減減)			
	    n異動數量 :=  oRec.盤盈數量-oRec.盤虧數量-oRec.報廢數量-oRec.樣品數量+oRec.加項數量-oRec.減項數量-oRec.損耗數量;
    	n期末數量 :=  oRec.期初數量+oRec.進貨數量-oRec.進退數量-oRec.銷貨數量+oRec.銷退數量 + (oRec.異動數量);
    
		--cSQL = format('alter table "%s" add column "%s" %s(%s,%s)'    ,$2 ,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        --execute cSQL;
		
		-- 2.單位成本 = 入之部金額 / 入之部數量
    	n異動金額2:=oRec.盤盈金額 -oRec.盤虧金額 +oRec.加項金額 -oRec.減項金額; -- 1256
    	n異動數量2:=oRec.盤盈數量 -oRec.盤虧數量 +oRec.加項數量 -oRec.減項數量; -- 1256
    	n單位成本 := ABS(Zerodiv( (n異動金額2+oRec.期初金額+oRec.進貨金額-oRec.進退金額-oRec.進折金額 ) , (n異動數量2+oRec.期初數量+oRec.進貨數量-oRec.進退數量  ), nDec));
    	if n單位成本=0 then    	
     		n單位成本 := oRec.標準成本;
    	end if;
    
    	-- 3.期末金額 =  期末數量 * 單位成本
    	n期末金額:= Round( n單位成本 * n期末數量,0);

    	-- 4.反推銷貨成本
    	n銷貨成本 := oRec.期初金額 + ( oRec.進貨金額 - oRec.進退金額 - oRec.進折金額 ) + oRec.加項金額 -oRec.減項金額  - n期末金額;

    	-- 5.存檔
   end loop ;

end; 
$_$;


ALTER PROCEDURE public."產品單筆計算"(IN cschema text, IN ctable text, IN cprno text, IN ndec double precision) OWNER TO postgres;

--
-- Name: 產品計算單筆(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."產品計算單筆"(cschema text, ctable text, cprno text, ndec integer) RETURNS TABLE("c品號" character varying, "n期末數量" numeric, "n期末金額" numeric, "n銷貨成本" numeric, "n單位成本" numeric)
    LANGUAGE plpgsql
    AS $_$
declare  
	oRec record;    
	
	
    /*
	n期末數量 numeric;	
	n期末金額 numeric;
	n單位成本 numeric;
	n銷貨成本 numeric;	
	*/
begin
	-- 0.假設銷貨及異動已經過帳到產品檔        	
    for oRec in EXECUTE format('select * from %s."%s" where "品號"=$1;',cSchema,cTable) Using cPrno 		
	Loop    		  
	    c品號 := oRec.品號;
		
		-- 1.期末數量 =(進產銷異動加加減減)				    
    	n期末數量 :=  oRec.期初數量+oRec.進貨數量-oRec.進退數量-oRec.銷貨數量+oRec.銷退數量 + (oRec.盤盈數量-oRec.盤虧數量-oRec.報廢數量-oRec.樣品數量+oRec.加項數量-oRec.減項數量-oRec.損耗數量);    
		-- 2.單位成本 = 入之部金額 / 入之部數量
				
    	n單位成本 := ABS(zerodiv( 
			(oRec.盤盈金額-oRec.盤虧金額+oRec.加項金額-oRec.減項金額 + oRec.期初金額+oRec.進貨金額-oRec.進退金額-oRec.進折金額 ) , 
			(oRec.盤盈數量-oRec.盤虧數量+oRec.加項數量-oRec.減項數量 + oRec.期初數量+oRec.進貨數量-oRec.進退數量  ), nDec));				
    	if n單位成本=0 then    	
     		n單位成本 := oRec.標準成本;
    	end if;    
    	-- 3.期末金額 =  期末數量 * 單位成本
    	n期末金額:= round( n單位成本 * n期末數量,0);
    	-- 4.反推銷貨成本
    	n銷貨成本 := oRec.期初金額 + ( oRec.進貨金額 - oRec.進退金額 - oRec.進折金額 ) + oRec.加項金額 -oRec.減項金額  - n期末金額;
    	-- 5.存檔		
		EXECUTE format('update %s."%s" set "期末數量"=$1,"期末金額"=$2,"銷貨成本"=$3,"單位成本"=$4 where "品號"=$5;',cSchema,cTable) Using n期末數量,n期末金額,n銷貨成本,n單位成本,c品號;	
		-- 6.回傳
		return Next; --  query EXECUTE format('select * from %s."%s" where "品號"=$1;',cSchema,cTable) Using c品號;
		
   end loop ;
end; 
$_$;


ALTER FUNCTION public."產品計算單筆"(cschema text, ctable text, cprno text, ndec integer) OWNER TO postgres;

--
-- Name: 產品計算多筆(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
