--
-- Name: 產生Schema(text, text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."產生Schema"(IN "cYear" text DEFAULT ''::text, IN "cComNo" text DEFAULT ''::text)
    LANGUAGE plpgsql
    AS $_$
declare
	Schema_Na text;
BEGIN
   -- 沒有帶入公司代號及年度 comm底下
   if trim($1) = '' and trim($2) = '' then
     Schema_Na := 'e3000__comm';
   -- 有帶入公司代號 沒有帶入年度 公司底下
   elsif trim($1) = '' then
     Schema_Na  := Format('e3000__data__%s', $2);
   -- 沒有帶入公司 有帶入年度 
   elsif trim($2) = '' then
     RETURN;  
   -- 有帶入公司 有帶入年度
   else
     Schema_Na  := Format('e3000__data__%s__%s', $2, $1);
   end if;
     
   EXECUTE FORMAT(' CREATE SCHEMA IF NOT EXISTS %I ', Schema_Na);
   
END;$_$;


ALTER PROCEDURE public."產生Schema"(IN "cYear" text, IN "cComNo" text) OWNER TO postgres;

--
-- Name: 產生同步資料結構(text, text, text, text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."產生同步資料結構"(IN cschema_std text, IN ctable_std text, IN cschema_targe text, IN ctable_targe text)
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2023/05/15 */	
	/* 1.用法: call public."資料結構同步"(...) --可省略public */    
	/* 2.依賴函數 public."資料結構"(...) --可省略public */	
    /* 3.可公用者 應置於 public 區 */	
    oRec record;
    /* 缺少之欄位 */
    t1 cursor for select aa.* from "資料結構"($1,$2) aa  where aa.field_name not in (select bb.field_name from "資料結構"($3,$4) bb );
    /* 相異之欄位  */
    t2 cursor for select aa.* from "資料結構"($1,$2) aa, "資料結構"($3,$4) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    /* */
    b1 boolean ;
    cSQL text;
	
begin
  if "schema存在否"($3)  then	
	cSQL = Format('CREATE SCHEMA IF NOT EXISTS %s',$2);
    execute cSQL;
  end if;	  
  if "表格存在否"($3,$4)  then
		
    --1.遇缺則補
    for oRec in t1 Loop    
	    if oRec.field_type='integer' then 
			--整數		
			cSQL = format('alter Table %s."%s" add column "%s" %s',$3,$4,oRec.field_name,oRec.field_type) ;
        elseif  Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s."%s" add column "%s" %s(%s,%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
            --有長度數字
            cSQL = format('alter table %s."%s" add column "%s" %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
            --有長度文字
            cSQL = format('alter Table %s."%s" add column "%s" %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
            --只有型態
            cSQL = format('alter Table %s."%s" add column "%s" %s',$3,$4,oRec.field_name,oRec.field_type) ;
        end if ;   
        --預設值        
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行        
        execute cSQL;
        
   end loop ;
   
    --2.相異則改  
    for oRec in t2 loop
        if Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s."%s" alter column "%s" type %s(%s,%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	                        
        elsif Not oRec.field_len = 0 then
            --有長度
            cSQL = format('alter Table %s."%s" alter column "%s" type %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len) ;
        elsif Not oRec.field_maxlen = 0 then
            --有長度
            cSQL = format('alter Table %s."%s" alter column "%s" type %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;            
        else     
            --只有型態
            cSQL = format('alter table %s."%s" alter column "%s" type %s',$3,$4,oRec.field_name,oRec.field_type) ;	
        end if ;           
        --執行        
        execute cSQL;
    end loop;
  else
	  cSQL = format('CREATE TABLE IF NOT EXISTS %s."%s"(  LIKE %s."%s" INCLUDING ALL)',$3,$4,$1,$2) ;
      execute cSQL;
      
  end if;
end; 
$_$;


ALTER PROCEDURE public."產生同步資料結構"(IN cschema_std text, IN ctable_std text, IN cschema_targe text, IN ctable_targe text) OWNER TO postgres;

--
-- Name: 立沖計算(text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."立沖計算"(IN cschema text)
    LANGUAGE plpgsql
    AS $_$
declare
    cTable0 text;
	cTable1 text;
	cTable2 text;
	cSQL text;
begin
	cTable0:=format('%s."總帳傳票立沖"',$1);
	-- 立帳及期初
	cTable1:=format('select Guid3,"立帳金額" as nA,"已沖金額" as nB,"未沖金額" as nC from %s where "立沖帳"<>''沖帳''  ',cTable0);
	-- 沖帳統計
	cTable2:=format('select vsGuid3,sum("沖帳金額") as Amt from %s where "立沖帳" =''沖帳'' Group by vsGuid3 ',cTable0);
	--更新 期初 立帳
	cSQL:=Format('update %s as t1 set "已沖金額"=t2.Amt,"未沖金額"=t1."立帳金額"-t2.Amt from (%s) as t2 where t1.Guid3=t2.vsguid3 and t1."立沖帳"<>''沖帳'';',cTable0,cTable2);
	execute cSQL;
	--更新 沖帳
	cSQL:=Format('update %s as t2 set "立帳金額"=t1.nA,"已沖金額"=t1.nB,"未沖金額"=t1.nC,"其他已沖金額"=t1.nB-t2."沖帳金額" from (%s) as t1 where t2.vsGuid3=t1.Guid3 and t2."立沖帳"=''沖帳'';',cTable0,cTable1);  
	execute cSQL;
end; 
$_$;


ALTER PROCEDURE public."立沖計算"(IN cschema text) OWNER TO postgres;

--
-- Name: 結構同步(text, text, text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."結構同步"(IN ctable_std text, IN ctable_targe text, IN cschema text)
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2023/05/05 例如: call public."結構同步"('std','targe','public') */
    oRec record;
    /* 缺少之欄位 */
    t1 cursor for select aa.* from 資料結構($3,$1) aa  where aa.field_name not in (select bb.field_name from 資料結構($3,$2) bb );
    /* 相異之欄位  */
    t2 cursor for select aa.* from 資料結構($3,$1) aa,資料結構($3,$2) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    cSQL text;
begin
    --1.遇缺則補
    for oRec in t1 Loop    
        if  Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table "%s" add column "%s" %s(%s,%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
            --有長度數字
            cSQL = format('alter table "%s" add column "%s" %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
            --有長度文字
            cSQL = format('alter Table "%s" add column "%s" %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
            --只有型態
            cSQL = format('alter Table "%s" add column "%s" %s',$2,oRec.field_name,oRec.field_type) ;
        end if ;   
        --預設值        
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行        
        execute cSQL;
        
   end loop ;
   
    --2.相異則改  
    for oRec in t2 loop
        if Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table "%s" alter column "%s" type %s(%s,%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	                        
        elsif Not oRec.field_len = 0 then
            --有長度
            cSQL = format('alter Table "%s" alter column "%s" type %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len) ;
        elsif Not oRec.field_maxlen = 0 then
            --有長度
            cSQL = format('alter Table "%s" alter column "%s" type %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;            
        else     
            --只有型態
            cSQL = format('alter table "%s" alter column "%s" type %s',$2,oRec.field_name,oRec.field_type) ;	
        end if ;           
        --執行        
        execute cSQL;
    end loop;
     
end; 
$_$;


ALTER PROCEDURE public."結構同步"(IN ctable_std text, IN ctable_targe text, IN cschema text) OWNER TO postgres;

--
-- Name: 總帳傳票與進銷差異(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳傳票與進銷差異"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "StartDate" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text) RETURNS TABLE("傳票日期" character varying, "傳票編號" character varying, "序" integer, "項目代號" character varying, "項目明細" character varying, "項目名稱" character varying, "摘要" character varying, "借方金額" numeric, "貸方金額" numeric, "差異金額" numeric, guid1 character varying, guid2 character varying)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_Prod Text;
	Table_MVou Text;
	Table_DVou Text;
	Table_Inv Text;
	oRec RECORD;
	nLen Integer;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na  := Format('e3000__data__%s__%s', $2, $1);
	Table_Prod := '總帳產品';  
	Table_MVou := '總帳傳票表頭';
	Table_DVou := '總帳傳票表身';
	Table_Inv  := '總帳傳票進銷';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_Prod 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_Prod, Table_Prod);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	
	-- 檢查表是否存在 進銷
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_Inv
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_Inv, Table_Inv);
	END IF;
	
	-- 從總帳會計項目撈取資料 並 建立一個 TEMP TABLE 用來回傳資料用
	DROP TABLE IF EXISTS TMP_InvDiff;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_InvDiff as
				   select t1."傳票日期", 
						  t1."傳票編號",
			   			  t1."序",
			              t1."項目代號",
			              t1."項目明細",
			   			  t1."項目名稱",
			              t1."摘要",
			              t1."借方金額",
			              t1."貸方金額",
						  (t1."借方金額"+t1."貸方金額" - coalesce(t2."金額", 0)) as "差異金額",
			              t1.guid1,
			              t1.guid2						  
				   from 
			       (
			         select * from %I.%I      
			         where guid1 in (select guid1 from %I.%I 
                                     where "過帳" = True and "傳票日期" Between $1 and $2)
			           and "項目明細" between ''1'' and ''6'' -- 只抓明細是1-6進銷科目
			        ) as t1
			        left join 
			       (
			         select guid2, sum("金額") as "金額" 
			         from %I.%I
			         where "品號" not in (select "品號" from %I.%I
			                             where "類別" = ''S'' )
			         group by guid2
			        ) as t2
			       on t1.guid2 = t2.guid2
			       order by "項目代號"  '
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_Inv
			   ,Schema_Na, Table_Prod)
	USING $3, $4;  
	
	RETURN Query select * from TMP_InvDiff order by "傳票日期", "傳票編號", "序";
		

END;
$_$;


ALTER FUNCTION public."總帳傳票與進銷差異"("cYear" text, "cCustNo" text, "StartDate" text, "EndDate" text) OWNER TO postgres;

--
-- Name: 總帳分類帳(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳分類帳"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "Accno1" text DEFAULT ''::text, "Accno2" text DEFAULT ''::text) RETURNS TABLE("項目代號" character varying, "項目名稱" character varying, "傳票日期" character varying, "傳票編號" character varying, "序" integer, "摘要" character varying, "借方金額" numeric, "貸方金額" numeric, guid1 character varying, guid2 character varying, "結餘" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
	BeginDate Text;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	-- 期初日期
	BeginDate := $1||'/01/01';
	
	
	-- 建立一個暫時的QUERY 將會計項目及傳票表身的內容合併 並篩選出只含已過帳資料
	DROP TABLE IF EXISTS TempTB_Ledger;
	EXECUTE 
		FORMAT('CREATE TEMPORARY TABLE TempTB_Ledger as
			    select * 
			    from 
			    (
			     select *,
			            (case when isdebit("項目代號") then 1 else -1 end 
			             * SUM("借方金額" - "貸方金額") OVER (PARTITION BY "項目代號" ORDER BY "傳票日期", "傳票編號", "序")) AS "結餘"
			     from
			     (
			      select "項目代號",
			             "項目名稱",
			             cast($1 as varchar(9)) as "傳票日期",
			   	       	 cast(''0000000'' as varchar(7)) as "傳票編號",
			   	  	     cast(0 as integer) as "序",
			   		     cast(''期初餘額'' as varchar(255)) as "摘要",
			   		     "期初借方金額" as "借方金額",
			   	         "期初貸方金額" as "貸方金額",
					     cast('''' as varchar(8)) as guid1,
			   		     cast('''' as varchar(8)) as guid2
			      from %I.%I
			      UNION ALL
			      select "項目代號", "項目名稱","傳票日期", 
			             "傳票編號", "序", "摘要",
			             "借方金額", "貸方金額", guid1, guid2
			      from %I.%I
			   	  where guid1 in (select guid1 from %I.%I where "過帳" = True)
			      Union All -- 併現收現支傳票的現金科目                                    
			      select cast(''1111'' as varchar(8)) as "項目代號",
			             cast(''現金'' as varchar(8)) as "項目名稱",
			             "傳票日期", "傳票編號",
			             cast(0 as integer) as "序",
			             cast('''' as varchar(255)) as "摘要",
			             sum("貸方金額") as "借方金額",
			             sum("借方金額") as "貸方金額",
			             guid1,
			             cast('''' as varchar(8)) as guid2
			      from %I.%I
			      where guid1 in (select guid1 from %I.%I 
			                      where "過帳" = True
			                        and "類別" in (''1'', ''2'') )
			     group by "傳票日期", "傳票編號", guid1
			    ) as tt 
			    where "項目代號" between $2 and $3
			    order by "項目代號", "項目名稱", "傳票日期", "傳票編號", "序"
			   ) as t1 '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	using BeginDate, $3, $4;
	
	RETURN Query select * from TempTB_Ledger;
END;
$_$;


ALTER FUNCTION public."總帳分類帳"("cYear" text, "cCustNo" text, "Accno1" text, "Accno2" text) OWNER TO postgres;

--
-- Name: 總帳存貨計算A(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳存貨計算A"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text, "cInvAccno" text DEFAULT ''::text) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
DECLARE
	-- 1131商品存貨、1132製成品存貨、1133在製品、1134原料、1135物料
	-- 5010期初存貨、5561期初製成品、5551期初在製品、5110期初原料、5210期初原料
	-- 5030期末存貨、5562期末製成品、5552期末在製品、5130期末原料、5230期末物料 
	InvArr Text[]:= ARRAY['1131', '1132', '1133', '1134', '1135'
						 ,'5010', '5561', '5551', '5110', '5210'
						 ,'5030', '5562', '5552', '5130', '5230'];
	cType Text;
	Schema_Na Text;
	Table_Prno text;
	
	Table_MVou text;
	Table_Inv text;
	Table_ProdChange text;
	NeedTB_Arr TEXT[];
	TBName Text;
	nCount integer;
	cSQL text;
	Amount numeric;
BEGIN
	-- 檢查帶入的參數(存貨科目) 是否正確
	if Not $4 = ANY(InvArr) then
		Return 0;
	End IF;
	
	-- 依科目判斷商品類別
	case
		when $4 IN ('1131', '5010', '5030') then cType := '1'; -- 商品
		when $4 IN ('1132', '5561', '5562') then cType := '2'; -- 製成品
		when $4 IN ('1133', '5551', '5552') then cType := '3'; -- 在製品
		when $4 IN ('1134', '5110', '5130') then cType := '4'; -- 原料
		when $4 IN ('1135', '5210', '5230') then cType := '5'; -- 物料
		else
			cType := '0';	-- 下腳
	end case;
	
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	
	-- 先檢查SCHEMA是否存在
    IF not EXISTS (
        SELECT 1
        FROM information_schema.schemata
        WHERE schema_name = Schema_Na -- ex. e3000__data__sample__111
    ) THEN
		EXECUTE 
			FORMAT(' CREATE SCHEMA IF NOT EXISTS %I ', Schema_Na);
	END IF; 
	
	-- 檢查產品資料是否存在且內是否有資料
	Table_Prno := '總帳產品';
	
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_Prno 
    ) THEN
		RETURN 0; --  產品資料TABLE不存在 代表進銷存沒資料 
	END IF;
	
	EXECUTE 
		FORMAT(' SELECT Count(*) FROM %I.%I ' , Schema_Na , Table_Prno)
	INTO nCount;
	IF nCount = 0 THEN
		RETURN 0; --  沒有產品資料 代表進銷存沒資料 應該?
	END IF;
	------------------------------------------

	-- 檢查TB
	Table_MVou       := '總帳傳票表頭';
	Table_Inv        := '總帳傳票進銷';
	Table_ProdChange := '總帳產品異動';
	
	-- 檢查傳票表頭TB 是否存在
	if not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查傳票進銷TB 是否存在
	if not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_Inv 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL ' 
				   , Schema_Na , Table_Inv, Table_Inv);
	END IF;
	
	-- 檢查產品異動TB 是否存在
	if not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_ProdChange 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL ' 
				   , Schema_Na , Table_ProdChange, Table_ProdChange);
	END IF;
			
	-- 串SQL指令 並執行
	EXECUTE 
	  Format(' select SUM("期末存貨") as "期末存貨" 
               from 
                ( 
                 (
                  select "品號"
                  from %I.%I                     
                  where "類別" = $1 
                   ) as t1
                  left join 
                  (
                   select "品號", 
                          (case when sum("可供銷售數量") = 0 then cast (0 as numeric(20,4)) 
                                else cast(round( (sum("可供銷售數量") -  sum("銷量淨額")) *  
                                                 (sum("可供銷售金額") / sum("可供銷售數量")),4 ) 
                                          as numeric(20,4)) 
                           end) as "期末存貨" 
                   from 
                   ( 
                    select  "品號",                                   
                            "期初數量" as "可供銷售數量", 
                            "期初金額" as "可供銷售金額", 
                            cast(0 as numeric(20,4)) as "銷量淨額" 
                    from %I.%I 								               	
                    Union all                                         
                    select  "品號", 									   
                            (case when "項目明細" = ''1'' then "數量" 
                                  when "項目明細" = ''2'' then "數量"*-1 
                                  else cast(0 as numeric(20,4)) 
                             end) as "可供銷售數量", 
                            (case when "項目明細" = ''1'' then "金額" 
                                  when "項目明細" = ''2'' then "金額"*-1 
                                  when "項目明細" = ''3'' then "金額"*-1 
                                  else cast(0 as numeric(20,4)) 
                             end) as "可供銷售金額", 
                            (case when "項目明細" = ''4'' then "數量" 
                                  when "項目明細" = ''5'' then "數量"*-1 
                                  else cast(0 as numeric(20,4)) 
                             end) as "銷量淨額" 
                    from %I.%I  
                    where guid1 in (select guid1 from %I.%I        
                                     where "過帳" = True and "傳票日期" <= $2 ) 
                    union all                                         -- 異動別1.2.5.6 的金額與數量會併入成本去計算單價(如同進貨)
                    select  "品號",                                    --      3.4.7 則不會(如同銷貨)
                            (case when "異動別" in (''1'', ''5'') then "數量" 
                                  when "異動別" in (''2'', ''6'') then "數量"*-1 
                                  else cast(0 as numeric(20,4))
                             end) as "可供銷售數量", 
                            (case when "異動別" in (''1'', ''5'') then "金額" 
                                  when "異動別" in (''2'', ''6'') then "金額"*-1 
                                  else cast(0 as numeric(20,4))
                             end) as "可供銷售金額", 
                            (case when "異動別" in (''3'', ''4'', ''7'') then "數量" 
                                  else cast(0 as numeric(20,4)) 
                             end) as "銷量淨額" 
                    from %I.%I  
                    where "異動日期" <= $2 
                    ) as tt 
                   group by "品號" 
                   order by "品號" 
                   ) as t2 
                   on t1."品號" = t2."品號" 
                  ) '
			 ,Schema_Na, Table_Prno 
			 ,Schema_Na, Table_Prno
			 ,Schema_Na, Table_Inv
			 ,Schema_Na, Table_MVou
			 ,Schema_Na, Table_ProdChange)
			 
	into Amount USING cType, $3 ; --帶入類別及日期參數
	
	RETURN Round(Amount,4);
END;
$_$;


ALTER FUNCTION public."總帳存貨計算A"("cYear" text, "cCustNo" text, "EndDate" text, "cInvAccno" text) OWNER TO postgres;

--
-- Name: 總帳存貨計算B(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳存貨計算B"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "Month" integer DEFAULT 0, "cInvAccno" text DEFAULT ''::text) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
DECLARE
    total_amount numeric := 0;
	Schema_Na Text;
	Table_Na Text;
	cMonthCol Text;
BEGIN
	-- 串出Schema及TABLE名稱
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_Na := '總帳存貨';
		
 	-- 檢查表是否存在
    IF EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_Na 
    ) THEN
	   
	    if $3 = 0 then 
		  cMonthCol := '期初金額';
		else
		  cMonthCol := Format('%s月金額', $3); -- 月份欄位名稱
		end if;
		
		
 		
		-- 動態SQL查詢
        EXECUTE 
			FORMAT(' SELECT %I FROM %I.%I
            		 WHERE "資產負債項目代號" = $1 or "損益期末項目代號" = $1 or "損益期初項目代號" = $1' 
            	  ,cMonthCol
				  ,Schema_Na 
				  ,Table_Na)
        INTO total_amount
        USING $4;

        -- 返回查詢到的金額
        RETURN COALESCE(total_amount,0);
    ELSE
        -- 表不存在，返回0
        RETURN 0;
    END IF;
END;
$_$;


ALTER FUNCTION public."總帳存貨計算B"("cYear" text, "cCustNo" text, "Month" integer, "cInvAccno" text) OWNER TO postgres;

--
-- Name: 總帳存貨計算C(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳存貨計算C"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text, "cInvAccno" text DEFAULT ''::text) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
DECLARE
    total_amount numeric := 0;
	Schema_Na Text;
	MVou_Na Text;
	DVou_Na Text;
BEGIN
	-- 串出Schema及TABLE名稱
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	MVou_Na := '總帳傳票表頭'; 
	DVou_Na := '總帳傳票表身';
		
 	-- 檢查總帳傳票表身是否存在(表身存在，一定有表頭)
    IF EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = DVou_Na 
    ) THEN 
		
		-- 動態SQL查詢
        EXECUTE 
			FORMAT(' SELECT sum("貸方金額") - sum("借方金額") 
				     FROM %I.%I
            		 WHERE "項目代號" = $1 
				       and guid1 in (select guid1 from %I.%I
				  					 where "過帳" = True and "傳票日期" <= $2 ) ' 
				  ,Schema_Na 
				  ,DVou_Na
				  ,Schema_Na
				  ,MVou_Na)
        INTO total_amount
        USING $4, $3;

        -- 返回查詢到的金額
        RETURN COALESCE(total_amount,0);
    ELSE
        -- 表不存在，返回0
        RETURN 0;
    END IF;
END;
$_$;


ALTER FUNCTION public."總帳存貨計算C"("cYear" text, "cCustNo" text, "EndDate" text, "cInvAccno" text) OWNER TO postgres;

--
-- Name: 總帳損益表(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳損益表"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "StartDate" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text) RETURNS TABLE("項目代號" character varying, "項目名稱" character varying, "金額" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
	oRec RECORD;
	nLen Integer;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	-- 從總帳會計項目撈取資料 並 建立一個 TEMP TABLE 用來回傳資料用
	DROP TABLE IF EXISTS TMP_IS;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_IS as
				   select t1."項目代號", 
						  t1."項目名稱",
						  coalesce(t2."金額", 0) as "金額" 
				   from 
			       (
			         select "項目代號", "項目名稱" 
			         from %I.%I
			         where left("項目代號", 1) >= $1
			        ) as t1
			        left join 
			       (
			         select "項目代號", 
                            (case                                                                     
                               when left("項目代號",1) in ($1, $2) then sum("貸方金額") - sum("借方金額")  
                               else sum("借方金額") - sum("貸方金額") 
			                 end ) as "金額" 
			         from %I.%I
			         where left("項目代號",1) >= $1  
                       and guid1 in (select guid1 from %I.%I 
                                     where "過帳" = True and "傳票日期" Between $3 and $4 )
			         group by "項目代號"
			        ) as t2
			       on t1."項目代號" = t2."項目代號"
			       order by "項目代號"  '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	USING '4', '7', $3, $4;  -- 4 與 7 開頭分別為營業收入，營業外收入
	
	
	/*
	FOR oRec in (select * from TMP_IS order by "項目代號")
	LOOP
	  nLen := Length(oRec."項目代號");
	  
	  -- 判斷是否為子目 子目不重新加總
	  if nLen > 4 then 
	    continue;
	  end if;
		
	  UPDATE TMP_IS as t1
	  SET "金額" = tt."加總"
	  FROM (
         SELECT SUM(t2."金額") as "加總"
	     FROM TMP_IS as t2
	     where left(t2."項目代號", nLen) = oRec."項目代號"
	    ) AS tt
	  where t1."項目代號" = oRec."項目代號";
	  	
	END LOOP;
	*/
	RETURN Query select * from TMP_IS order by "項目代號";
		

END;
$_$;


ALTER FUNCTION public."總帳損益表"("cYear" text, "cCustNo" text, "StartDate" text, "EndDate" text) OWNER TO postgres;

--
-- Name: 總帳日記帳(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳日記帳"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text) RETURNS TABLE("傳票日期" character varying, "傳票編號" character varying, "序" integer, "項目代號" character varying, "項目名稱" character varying, "摘要" character varying, "借方金額" numeric, "貸方金額" numeric, guid1 character varying, guid2 character varying)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
	BeginDate Text;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	
	-- 期初日期
	BeginDate := $1||'/01/01';
	
	
	-- 建立一個暫時的QUERY 將會計項目及傳票表身的內容合併 並篩選出只含已過帳資料
	DROP TABLE IF EXISTS TempTB_Jour;
	EXECUTE 
		FORMAT('CREATE TEMPORARY TABLE TempTB_Jour as
			    select * from
			    ( 
			     select cast($1 as varchar(9)) as "傳票日期",
			            cast(''0000000'' as varchar(7)) as "傳票編號",
			   	   	    cast(0 as integer) as "序",
			   		    "項目代號",
			   	        "項目名稱",
			   		    cast(''上年度節轉'' as varchar(255)) as "摘要",
			   		    "期初借方金額" as "借方金額",
			   	        "期初貸方金額" as "貸方金額",
					    cast(''0000000'' as varchar(32)) as guid1,
			   		    cast("項目代號" as varchar(32)) as guid2
			     from %I.%I
			     where ("期初借方金額"+"期初貸方金額") <> 0
			     UNION ALL
			     select "傳票日期", "傳票編號", "序",
			            "項目代號", "項目名稱", "摘要",
			            "借方金額", "貸方金額", guid1, guid2
			     from %I.%I
			   	 where guid1 in (select guid1 from %I.%I where "過帳" = True)
			     Union All -- 併現收現支傳票的現金科目                                    
			     select "傳票日期", "傳票編號",
			            cast(0 as integer) as "序",
			            cast(''1111'' as varchar(8)) as "項目代號",
			            cast(''現金'' as varchar(8)) as "項目名稱",
			            cast('''' as varchar(255)) as "摘要",
			            sum("貸方金額") as "借方金額",
			            sum("借方金額") as "貸方金額",
			            guid1,
			            cast(''1111'' as varchar(32)) as guid2
			     from %I.%I
			     where guid1 in (select guid1 from %I.%I 
			                     where "過帳" = True
			                       and "類別" in (''1'', ''2'') )
			     group by "傳票日期", "傳票編號", guid1
			    )
                order by "傳票編號", "序", guid2  '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	using BeginDate;
	
	RETURN Query select * from TempTB_Jour;
	
END;
$_$;


ALTER FUNCTION public."總帳日記帳"("cYear" text, "cCustNo" text) OWNER TO postgres;

--
-- Name: 總帳現金帳(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳現金帳"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text) RETURNS TABLE("傳票日期" character varying, "傳票編號" character varying, "序" integer, "項目代號" character varying, "項目名稱" character varying, "摘要" character varying, "借方金額" numeric, "貸方金額" numeric, guid1 character varying, guid2 character varying, "結餘" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
	BeginDate Text;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	
	-- 期初日期
	BeginDate := $1||'/01/01';
	
	
	-- 建立一個暫時的QUERY 將會計項目及傳票表身的內容合併 並篩選出只含已過帳資料
	DROP TABLE IF EXISTS TempTB_Cash;
	EXECUTE 
		FORMAT('CREATE TEMPORARY TABLE TempTB_Cash as
			    select *,
			            SUM("借方金額" - "貸方金額") OVER (ORDER BY "傳票日期", "傳票編號", "序") AS "結餘"
			    from
			    (
			     select cast($1 as varchar(9)) as "傳票日期",
			   	      	cast(''0000000'' as varchar(7)) as "傳票編號",
			            cast(0 as integer) as "序",
			            "項目代號",
			            "項目名稱",
			   	        cast(''期初餘額'' as varchar(255)) as "摘要",
			   		    "期初借方金額" as "借方金額",
			   	        "期初貸方金額" as "貸方金額",
					    cast('''' as varchar(32)) as guid1,
			   		    cast('''' as varchar(32)) as guid2
			      from %I.%I
			      where "項目代號" = $2
			      UNION ALL                           -- 抓"轉帳"傳票現金科目
			      select "傳票日期", "傳票編號", "序", 
			             "項目代號", "項目名稱", "摘要",  
			             "借方金額", "貸方金額", 
			             guid1, guid2 
			      from %I.%I
			   	  where "項目代號" = $2
			        and guid1 in (select guid1 from %I.%I where "過帳" = True)
			      Union All                           -- 併"現收" "現支"傳票的科目(現金的對項科目)                                    
			      select "傳票日期", "傳票編號", "序", 
			             "項目代號", "項目名稱", "摘要",  
			             "貸方金額" as "借方金額",       -- 借貸要翻轉
			             "借方金額" as "貸方金額", 
			             guid1, guid2         
			      from %I.%I
			      where guid1 in (select guid1 from %I.%I 
			                      where "過帳" = True
			                        and "類別" in (''1'', ''2'') )
			     ) as tt 
			     order by "傳票日期", "傳票編號", "序" '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	using BeginDate, '1111';
	
	RETURN Query select * from TempTB_Cash;
	
END;
$_$;


ALTER FUNCTION public."總帳現金帳"("cYear" text, "cCustNo" text) OWNER TO postgres;

--
-- Name: 總帳產品異動彙總(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳產品異動彙總"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text) RETURNS TABLE("異動日期" character varying, "盤盈金額" numeric, "盤虧金額" numeric, "報廢金額" numeric, "樣品金額" numeric, "其他加項金額" numeric, "其他減項金額" numeric, "耗損金額" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_ProdChg Text;
	nn integer;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_ProdChg := '總帳產品異動';
	
	 -- 檢查表是否存在 總帳產品異動 TB
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_ProdChg 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_ProdChg, Table_ProdChg);
	END IF;  
	
	
	
	-- 建立一個暫時的QUERY 將會計項目及傳票表身的內容合併 並篩選出只含已過帳資料
	DROP TABLE IF EXISTS TempTB_SumProdChg;
	EXECUTE 
		FORMAT('CREATE TEMPORARY TABLE TempTB_SumProdChg as
			    select tt."異動日期" as "異動日期",
			           SUM(tt."盤盈金額") as "盤盈金額",
			           SUM(tt."盤虧金額") as "盤虧金額",
			           SUM(tt."報廢金額") as "報廢金額",
			           SUM(tt."樣品金額") as "樣品金額",
			           SUM(tt."其他加項金額") as "其他加項金額",
			           SUM(tt."其他減項金額") as "其他減項金額",
			           SUM(tt."耗損金額") as "耗損金額"
			    from 
			    (
                 select "異動日期",
			            (case when "異動別" = ''1'' then "金額" else 0 end) as "盤盈金額",
			            (case when "異動別" = ''2'' then "金額" else 0 end) as "盤虧金額",
						(case when "異動別" = ''3'' then "金額" else 0 end) as "報廢金額",
						(case when "異動別" = ''4'' then "金額" else 0 end) as "樣品金額",
						(case when "異動別" = ''5'' then "金額" else 0 end) as "其他加項金額",
						(case when "異動別" = ''6'' then "金額" else 0 end) as "其他減項金額",
						(case when "異動別" = ''7'' then "金額" else 0 end) as "耗損金額"
			     from %I.%I
			     ) as tt
			   group by "異動日期" '
			   ,Schema_Na, Table_ProdChg);
	
	RETURN Query select * from TempTB_SumProdChg;
	
END;
$_$;


ALTER FUNCTION public."總帳產品異動彙總"("cYear" text, "cCustNo" text) OWNER TO postgres;

--
-- Name: 總帳票據開立明細(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳票據開立明細"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "cDtl" text DEFAULT ''::text) RETURNS TABLE("項目代號" character varying, "項目明細" character varying, "託收" boolean, "兌現" boolean, "到期日" character varying, "收開票日" character varying, "統編" character varying, "名稱" character varying, "票號" character varying, "票據金額" numeric, "傳票編號" character varying, "沖轉項目" character varying, guid3 character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    Schema_Na TEXT;
    Table_MVou TEXT; -- 總帳傳票表頭
    Table_DVou TEXT; -- 總帳傳票表身
    Table_Bill TEXT; -- 總帳傳票票據
    
    NeedTB_Arr TEXT[];
    TBName TEXT;
BEGIN

    -- 檢查產品資料TB是否存在，且是否有資料
    Schema_Na := Format('e3000__data__%s__%s', $2, $1);
    
    -- 先檢查SCHEMA是否存在
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.schemata
        WHERE schema_name = Schema_Na -- ex. e3000__data__sample__111
    ) THEN
        EXECUTE FORMAT('CREATE SCHEMA IF NOT EXISTS %I', Schema_Na);
    END IF; 
    
    -- 將需要的TB放在ARR中並透過迴圈檢查是否存在並產生
    Table_MVou := '總帳傳票表頭'; 
    Table_DVou := '總帳傳票表身'; 
    Table_Bill := '總帳傳票票據'; 

    NeedTB_Arr := ARRAY[Table_MVou, Table_DVou, Table_Bill];
    FOREACH TBName IN ARRAY NeedTB_Arr 
    LOOP
        -- 依序檢查表是否存在 
        IF NOT EXISTS (
            SELECT 1
            FROM information_schema.tables
            WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
            AND table_name = TBName
        ) THEN
            EXECUTE FORMAT('CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL)', Schema_Na , TBName, TBName);
        END IF;  
    END LOOP;
        
    -- 執行查詢並返回結果
    RETURN QUERY EXECUTE 
        FORMAT('SELECT "項目代號", "項目明細", "託收", 
                       "兌現", "到期日", "收開票日",  
                       "統編", "名稱", "票號",  
                       "票據金額", "傳票編號", "沖轉項目", guid3  
                FROM %I.%I 
                WHERE "項目明細" = $1 -- B應收票據 或 D 應付票據
                AND 
                (guid1 = ''0000000''
                 OR  
                 guid2 IN 
			       (
                    SELECT guid2 
                    FROM %I.%I -- 傳票表身
                    WHERE guid1 IN (
                        SELECT guid1 
                        FROM %I.%I -- 傳票表頭判斷只抓有過帳
                        WHERE "過帳" = True
                        )  
                    AND ( -- B應收票據 抓有借方金額 D應付票據 抓有貸方金額
                        ("項目明細" = ''B'' AND "借方金額" > 0)
                        OR 
                        ("項目明細" = ''D'' AND "貸方金額" > 0)
                        )
                    )
                 ) '
            ,Schema_Na, Table_Bill
            ,Schema_Na, Table_DVou
            ,Schema_Na, Table_MVou)
    USING $3;
    
END;
$_$;


ALTER FUNCTION public."總帳票據開立明細"("cYear" text, "cCustNo" text, "cDtl" text) OWNER TO postgres;

--
-- Name: 總帳試算表(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳試算表"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "StartDate" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text) RETURNS TABLE("項目代號" character varying, "項目名稱" character varying, "期初借方餘額" numeric, "期初貸方餘額" numeric, "本期借方金額" numeric, "本期貸方金額" numeric, "期末借方餘額" numeric, "期末貸方餘額" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
	oRec RECORD;
	nBeginDiff numeric;
	nDiff numeric;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	-- 從總帳會計項目撈取資料 並 建立一個 TEMP TABLE 用來回傳資料用
	DROP TABLE IF EXISTS TMP_SpreadSheet;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_SpreadSheet as
				   select "項目代號", "項目名稱", 
						  "期初借方金額" as "期初借方餘額",
						  "期初貸方金額" as "期初貸方餘額", 
						  cast(0 as numeric(20,4)) as "本期借方金額",
						  cast(0 as numeric(20,4)) as "本期貸方金額",
						  cast(0 as numeric(20,4)) as "期末借方餘額",
						  cast(0 as numeric(20,4)) as "期末貸方餘額"
				   from %I.%I 
				   where Length("項目代號") >=4  
			   		 and "項目代號" not in (select left("項目代號", 4)      
			   							   from %I.%I
			                               where Length("項目代號") > 4) '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_XMaster);
	
	-- 用傳票表身產生暫時的資料 
	DROP TABLE IF EXISTS TMP_Vou;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_Vou as
				select "項目代號",  
				       SUM(CASE WHEN "傳票日期" < $1 THEN "借方金額" ELSE 0 END	) AS "期初借方",
					   SUM(CASE WHEN "傳票日期" < $1 THEN "貸方金額" ELSE 0 END ) AS "期初貸方",	  
					   SUM(CASE WHEN "傳票日期" BETWEEN $1 AND $2 THEN "借方金額" ELSE 0 END ) AS "本期借方",		  
					   SUM(CASE WHEN "傳票日期" BETWEEN $1 AND $2 THEN "貸方金額" ELSE 0 END ) AS "本期貸方"
							  		
				from 
			    (
			     select"項目代號", "傳票日期", 
                       "借方金額", "貸方金額",
			           guid1, guid2
			     from %I.%I
			     where guid1 in (select guid1 from %I.%I 
				 				 where "過帳" = True
								   and "傳票日期" <= $2 )
			     Union All  -- 併現收現支傳票的現金科目
			     select cast(''1111'' as varchar(8)) as "項目代號",
			            "傳票日期",
			            sum("貸方金額") as "借方金額",
			            sum("借方金額") as "貸方金額",
			            guid1,
			            cast('''' as varchar(8)) as guid2
			     from %I.%I
			     where guid1 in (select guid1 from %I.%I 
			                     where "過帳" = True
			                       and "類別" in (''1'', ''2'') 
			                       and "傳票日期" <= $2 )
			     group by "傳票日期", guid1
				) as tt
				Group by "項目代號" '	
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	USING $3, $4;
	
	FOR oRec in select * from TMP_Vou
	LOOP
		-- 判斷期初借減貸 
		nBeginDiff := oRec."期初借方" - oRec."期初貸方";
		-- 判斷本期借減貸
		nDiff      := oRec."本期借方" - oRec."本期貸方";
		
		-- 依序更改暫存試算表的金額
		UPDATE TMP_SpreadSheet as t1
		SET
			"期初借方餘額" = 
				CASE 
					when t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff < 0 THEN 0
					else t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff 
				END,
			"期初貸方餘額" = 
				CASE 
					when t1."期初借方餘額" - t1."期初貸方餘額"+ nBeginDiff < 0 
					THEN (t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff)*-1
					else 0
				END,
			"本期借方金額" = oRec."本期借方", 
			"本期貸方金額" = oRec."本期貸方",
			"期末借方餘額" =
				CASE 
					when t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff + nDiff < 0 THEN 0
					else t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff + nDiff
				END,
			"期末貸方餘額" =
				CASE 
					when t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff + nDiff < 0 
					THEN (t1."期初借方餘額" - t1."期初貸方餘額" + nBeginDiff + nDiff)*-1
					else 0
				END
		where 
			t1."項目代號" = oRec."項目代號";
	END LOOP;
	
	-- 最後將本期傳票中未出現的會計科目 => 期初金額移置期末
	UPDATE TMP_SpreadSheet as t2
	SET "期末借方餘額" = t2."期初借方餘額",
		"期末貸方餘額" = t2."期初貸方餘額"
	where
		t2."項目代號" not in (select t3."項目代號" from TMP_Vou as t3);
		
	RETURN Query 
		select * from TMP_SpreadSheet tt
		where tt."期初借方餘額" <> 0 or tt."期初貸方餘額" <> 0
		   or tt."本期借方金額" <> 0 or tt."本期貸方金額" <> 0
		   or tt."期末借方餘額" <> 0 or tt."期末貸方餘額" <> 0
		order by tt."項目代號";
END;
$_$;


ALTER FUNCTION public."總帳試算表"("cYear" text, "cCustNo" text, "StartDate" text, "EndDate" text) OWNER TO postgres;

--
-- Name: 總帳資產負債表(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳資產負債表"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text) RETURNS TABLE("項目代號" character varying, "項目名稱" character varying, "金額" numeric)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text;
	Table_MVou Text;
	Table_DVou Text;
BEGIN
	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na := Format('e3000__data__%s__%s', $2, $1);
	Table_XMaster := '總帳會計項目';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	
	 -- 檢查表是否存在 會計項目
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_XMaster 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_XMaster, Table_XMaster);
	END IF;  
	
	-- 檢查表是否存在 傳票表頭
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_MVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_MVou, Table_MVou);
	END IF;
	
	-- 檢查表是否存在 傳票表身
    IF not EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
        AND table_name = Table_DVou 
    ) THEN
		EXECUTE 
			FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
				   , Schema_Na , Table_DVou, Table_DVou);
	END IF;
	
	-- 從總帳會計項目撈取資料 並 建立一個 TEMP TABLE 用來回傳資料用
	DROP TABLE IF EXISTS TMP_FS;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_FS as
				   select t1."項目代號", 
						  t1."項目名稱",
						  coalesce(t2."金額", 0) as "金額" 
				   from 
			       (
			         select "項目代號", "項目名稱" 
			         from %I.%I
			         where left("項目代號", 1) <= $1
			        ) as t1
			        left join 
			       (
			         select "項目代號", 
                            (case                                                                     
                               when isdebit("項目代號") then sum("借方金額") - sum("貸方金額")   
                               else sum("貸方金額") - sum("借方金額") 
			                 end ) as "金額" 
			         from 
			         (
			          select "項目代號", 
			                 "期初借方金額" as "借方金額",
			                 "期初貸方金額" as "貸方金額"
					  from %I.%I
					  where left("項目代號", 1) <= $1
			          Union ALL  -- 併本期傳票
			          select "項目代號", "借方金額", "貸方金額"
			          from %I.%I
			          where left("項目代號",1) <= $1  
                       and guid1 in (select guid1 from %I.%I 
                                     where "過帳" = True and "傳票日期" <= $2)
			          Union ALL  -- 併現收現支傳票的現金科目 
			          select cast(''1111'' as varchar(8)) as "項目代號",
			                 sum("貸方金額") as "借方金額", 
			                 sum("借方金額") as "貸方金額"
			          from %I.%I
			          where guid1 in (select guid1 from %I.%I 
			                          where "過帳" = True 
			                            and "傳票日期" <= $2
			                            and "類別" in (''1'', ''2'') ) 
			          ) as tt
			        group by "項目代號"
			        ) as t2
			       on t1."項目代號" = t2."項目代號"
			       order by "項目代號"  '
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou)
	USING '3', $3;  -- 只抓開頭是3以下的實科目 包含3
		
	RETURN Query select * from TMP_FS order by "項目代號";
END;
$_$;


ALTER FUNCTION public."總帳資產負債表"("cYear" text, "cCustNo" text, "EndDate" text) OWNER TO postgres;

--
-- Name: 總帳進銷平均單價異常檢查(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳進銷平均單價異常檢查"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "DataType" text DEFAULT '1'::text, "Prno1" text DEFAULT ''::text, "Prno2" text DEFAULT ''::text) RETURNS TABLE("傳票編號" character varying, "序" integer, "品號" character varying, "品名" character varying, "數量" numeric, "單價" numeric, "金額" numeric, "平均單價" numeric, "單價差異" numeric, "差異百分比" numeric, guid1 character varying, guid2 character varying, guid3 character varying)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_MVou Text;
	Table_Prod Text;
	Table_Inv Text;
	NeedTB_Arr TEXT[];
	TBName Text;
	cDtl1 Text;
	cDtl2 Text;
    cDtl3 Text;
BEGIN

    -- 根據參數判斷要抓進貨還是銷貨資料
	if $3 = '1' then
	  cDtl1 = '1';
	  cDtl2 = '2';
	  cDtl3 = '3';
	else
	  cDtl1 = '4';
	  cDtl2 = '5';
	  cDtl3 = '6';
	end if;


	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na  := Format('e3000__data__%s__%s', $2, $1);
	
	-- 先檢查SCHEMA是否存在
    IF not EXISTS (
        SELECT 1
        FROM information_schema.schemata
        WHERE schema_name = Schema_Na -- ex. e3000__data__sample__111
    ) THEN
		EXECUTE 
			FORMAT(' CREATE SCHEMA IF NOT EXISTS %I ', Schema_Na);
	END IF; 
	
	
	-- 將需要的TB放在ARR中並透過迴圈檢查是否存在並產生
	Table_MVou := '總帳傳票表頭';
	Table_Prod := '總帳產品';
	Table_Inv  := '總帳傳票進銷';
	
	NeedTB_Arr := ARRAY[Table_MVou , Table_Prod , Table_Inv];
    FOREACH TBName IN ARRAY NeedTB_Arr 
	LOOP
        -- 依序檢查表是否存在 
		IF not EXISTS (
			SELECT 1
			FROM information_schema.tables
			WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
			AND table_name = TBName
		) THEN
			EXECUTE 
				FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
					   , Schema_Na , TBName, TBName);
		END IF;  
    END LOOP;
		
	-- 從總帳會計項目撈取資料 並 建立一個 TEMP TABLE 用來回傳資料用
	DROP TABLE IF EXISTS TMP_InvChkUP;
	EXECUTE
		FORMAT('CREATE TEMPORARY TABLE TMP_InvChkUP as
				select t1."傳票編號" as "傳票編號",
                       t1."序"   as "序", 
                       t1."品號" as "品號", 
                       t1."品名" as "品名", 
                       t1."數量" as "數量", 
                       t1."單價" as "單價", 
                       t1."金額" as "金額", 
                       t2."平均單價" as "平均單價", 
                       t1."單價"- t2."平均單價" as "單價差異", 
                       ((t1."單價"- t2."平均單價") / t2."平均單價") * 100  as "差異百分比",
			           t1.guid1 as guid1,
			           t1.guid2 as guid2,
			           t1.guid3 as guid3
                from 
                ( 
                 select * from %I.%I 
                 where "品號" between $1 and $2 
                   and "項目明細" in($3, $4) -- 只抓1,2 進貨 進退 4,5 銷貨 消退 依照參數判斷
                  ) as t1 
                left join  -- 用進銷存表頭做JOIN
                ( 
                 select "品號", 
                        (case when sum("可供銷售數量") = 0 then cast(0 as numeric(20,4)) 
                              else cast(Round(sum("可供銷售金額") / sum("可供銷售數量"), 4) as numeric(20,4))  
                         end) as "平均單價" 
                 from 
                 (                   -- 期初 + 進銷存 + 產品異動
                  select  "品號", 
                          "期初數量" as "可供銷售數量", 
                          "期初金額" as "可供銷售金額" 
                  from %I.%I 
                  union all 
                  select  "品號", 
                          (case when "項目明細" = $3 then "數量" 
                                when "項目明細" = $4 then "數量"*-1 
                                else cast(0 as numeric(20,4)) 
                           end) as "可供銷售數量", 
                          (case when "項目明細" = $3 then "金額" 
                                when "項目明細" = $4 then "金額"*-1 
                                when "項目明細" = $5 then "金額"*-1 
                                else cast(0 as numeric(20,4)) 
                           end) as "可供銷售金額" 
                  from %I.%I 
                  where guid1 in (select guid1 from %I.%I 
                                  where "過帳" = True ) 
                  ) as tt 
                 group by "品號" 
                 ) as t2 
                on t1."品號" = t2."品號" 
                order by "品號" ' 
			   ,Schema_Na, Table_Inv
			   ,Schema_Na, Table_Prod
			   ,Schema_Na, Table_Inv
			   ,Schema_Na, Table_MVou)
	USING $4, $5, cDtl1, cDtl2, cDtl3;  
	
	RETURN Query select * from TMP_InvChkUP;
		

END;
$_$;


ALTER FUNCTION public."總帳進銷平均單價異常檢查"("cYear" text, "cCustNo" text, "DataType" text, "Prno1" text, "Prno2" text) OWNER TO postgres;

--
-- Name: 總帳餘額統計(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳餘額統計"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "EndDate" text DEFAULT ''::text, "cDtl" text DEFAULT ''::text) RETURNS TABLE("統編" character varying, "名稱" character varying, "金額" numeric, "項目代號" character varying)
    LANGUAGE plpgsql
    AS $_$
Declare
	Schema_Na Text;
	Table_XMaster Text; -- 總帳會計項目
	Table_CS   Text; -- 總帳客戶廠商
	Table_MVou Text; -- 總帳傳票表頭
	Table_DVou Text; -- 總帳傳票表身
 	Table_Bal Text;  -- 總帳傳票餘額
	
	NeedTB_Arr TEXT[];
	TBName Text;
BEGIN

	-- 檢查產品資料TB是否存在，且是否有資料
	Schema_Na  := Format('e3000__data__%s__%s', $2, $1);
	
	-- 先檢查SCHEMA是否存在
    IF not EXISTS (
        SELECT 1
        FROM information_schema.schemata
        WHERE schema_name = Schema_Na -- ex. e3000__data__sample__111
    ) THEN
		EXECUTE 
			FORMAT(' CREATE SCHEMA IF NOT EXISTS %I ', Schema_Na);
	END IF; 
	
	
	-- 將需要的TB放在ARR中並透過迴圈檢查是否存在並產生
	Table_XMaster := '總帳會計項目';
	Table_CS      := '總帳客戶廠商';
	Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
 	Table_Bal     := '總帳傳票餘額'; 

	
	NeedTB_Arr := ARRAY[Table_XMaster, Table_CS, Table_MVou ,Table_DVou, Table_Bal];
    FOREACH TBName IN ARRAY NeedTB_Arr 
	LOOP
        -- 依序檢查表是否存在 
		IF not EXISTS (
			SELECT 1
			FROM information_schema.tables
			WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
			AND table_name = TBName
		) THEN
			EXECUTE 
				FORMAT(' CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL) ' 
					   , Schema_Na , TBName, TBName);
		END IF;  
    END LOOP;
		
    -- 執行查詢並返回結果
    RETURN QUERY EXECUTE 
		FORMAT('select t1."統編" as "統編",
			           COALESCE(t2."名稱", '''') as "名稱",
			           t1."金額" as "金額",
			           t1."項目代號" as "項目代號"
                from 
			    (
			     select "統編", sum("金額") as "金額", "項目代號"
			     from 
                 (
			      -- 期初資料
			      
			      select "統編", "金額", "項目代號"
			      from %I.%I
			      where guid1 = ''00000000''
			        and "項目代號" in (select "項目代號" from %I.%I  
			                          where "項目明細" = $2) --只抓1-1項目明細相同的資料 A應收 或B應付
			      
			      Union all
			    
			      -- 本期資料
			      Select COALESCE(C."統編", '''') as "統編",
			             case when $2 = ''A'' then B."借方金額" - B."貸方金額" -- A.應收 用貸-借 表示正負餘額
			                  when $2 = ''C'' then B."貸方金額" - B."借方金額" -- C.應付 用貸-借 表示正負餘額 
			                  else 0
			             end as "金額",
			             B."項目代號"
			      from %I.%I B  -- 傳票表身  
			      Left join %I.%I A on A.Guid1 = B.Guid1 -- 傳票表頭
			      Left join %I.%I C on B.Guid2 = C.Guid2 -- 傳票餘額  
			      where A."過帳" = True
			        and A."傳票日期" <= $1
			        and B."項目明細" = $2
			      ) as tt
			     group by "統編", "項目代號" 
			     ) as t1
			    left join 
			      %I.%I as t2  
			    on t1."統編" = t2."統編" ' 
			   ,Schema_Na, Table_Bal
			   ,Schema_Na, Table_XMaster
			   ,Schema_Na, Table_DVou
			   ,Schema_Na, Table_MVou 
			   ,Schema_Na, Table_Bal
			   ,Schema_Na, Table_CS)
	Using $3, $4 ;  
			

END;
$_$;


ALTER FUNCTION public."總帳餘額統計"("cYear" text, "cCustNo" text, "EndDate" text, "cDtl" text) OWNER TO postgres;

--
-- Name: 總帳餘額逐筆明細(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."總帳餘額逐筆明細"("cYear" text DEFAULT ''::text, "cCustNo" text DEFAULT ''::text, "cDtl" text DEFAULT ''::text) RETURNS TABLE("傳票日期" character varying, "傳票編號" character varying, "統編" character varying, "名稱" character varying, "金額" numeric, "項目代號" character varying, guid1 character varying, guid2 character varying, guid3 character varying, "沖轉" boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    Schema_Na TEXT;
	Table_XMaster TEXT; -- 總帳會計項目
    Table_MVou TEXT; -- 總帳傳票表頭
	Table_DVou TEXT; -- 總帳傳票表身
	Table_CS   TEXT; -- 總帳客戶廠商
    Table_ARAP TEXT; -- 總帳傳票餘額
    
    NeedTB_Arr TEXT[];
    TBName TEXT;
BEGIN

    -- 檢查產品資料TB是否存在，且是否有資料
    Schema_Na := Format('e3000__data__%s__%s', $2, $1);
    
    -- 先檢查SCHEMA是否存在
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.schemata
        WHERE schema_name = Schema_Na -- ex. e3000__data__sample__111
    ) THEN
        EXECUTE FORMAT('CREATE SCHEMA IF NOT EXISTS %I', Schema_Na);
    END IF; 
    
    -- 將需要的TB放在ARR中並透過迴圈檢查是否存在並產生
	Table_XMaster := '總帳會計項目';
    Table_MVou    := '總帳傳票表頭';
	Table_DVou    := '總帳傳票表身';
	Table_CS      := '總帳客戶廠商';
    Table_ARAP    := '總帳傳票餘額'; 

    NeedTB_Arr := ARRAY[Table_XMaster, Table_MVou, Table_DVou, Table_CS, Table_ARAP];
    FOREACH TBName IN ARRAY NeedTB_Arr 
    LOOP
        -- 依序檢查表是否存在 
        IF NOT EXISTS (
            SELECT 1
            FROM information_schema.tables
            WHERE table_schema = Schema_Na -- ex. e3000__data__sample__111
            AND table_name = TBName
        ) THEN
            EXECUTE FORMAT('CREATE TABLE IF NOT EXISTS %I.%I (LIKE e3000__std.%I INCLUDING ALL)', Schema_Na , TBName, TBName);
        END IF;  
    END LOOP;
        
    -- 執行查詢並返回結果
    RETURN QUERY EXECUTE 	   
		FORMAT('SELECT t1."傳票日期" as "傳票日期",
			           t1."傳票編號" as "傳票編號",
			           t1."統編" as "統編",
			           COALESCE(t2."名稱", '''') as "名稱",
			           t1."金額" as "金額",
			           t1."項目代號" as "項目代號",
			           t1.guid1 as guid1,
			   		   t1.guid2 as guid2,
			   		   t1.guid3 as guid3,
		               t1."沖轉" as "沖轉"  
                FROM 
			    (
			      -- 期初資料
			      
			      select cast('''' as varchar(9)) as "傳票日期", "傳票編號", "統編", "金額", 
			            "項目代號", guid1, guid2, guid3, "沖轉" 
			      from %I.%I
			      where guid1 = ''00000000''
			        and "項目代號" in (select "項目代號" from %I.%I  
			                          where "項目明細" = $1) --只抓1-1項目明細相同的資料 A應收 或C應付
			      
			      Union all
			   
			      -- 本期資料
			      select A."傳票日期", A."傳票編號", C."統編", C."金額", 
			             B."項目代號", C.guid1, C.guid2, C.guid3, C."沖轉"
			      from %I.%I A, %I.%I B, %I.%I C
			      where A.Guid1 = B.Guid1 and B.Guid2 = C.Guid2
			        and (case when $1 = ''A'' then B."借方金額" > 0  -- A.應收 只抓借方有金額
			                  when $1 = ''C'' then B."貸方金額" > 0  -- C.應付 只抓貸方有金額
			                  else False
			             end)
			     ) as t1
			    left join 
			       %I.%I as t2
			    on t1."統編" = t2."統編" '
            ,Schema_Na, Table_ARAP
            ,Schema_Na, Table_XMaster
            ,Schema_Na, Table_MVou
			,Schema_Na, Table_DVou
			,Schema_Na, Table_ARAP
			,Schema_Na, Table_CS)
	Using $3;  
    
END;
$_$;


ALTER FUNCTION public."總帳餘額逐筆明細"("cYear" text, "cCustNo" text, "cDtl" text) OWNER TO postgres;

--
-- Name: 表格存在否(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."表格存在否"(schemafilter text, tbn text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare ii integer;
begin
	SELECT count(*) FROM pg_namespace cc,pg_class dd 
	where cc.oid=dd.relnamespace and nspname=$1 and dd.relname=$2 into ii;
return (ii>0);
end;
$_$;


ALTER FUNCTION public."表格存在否"(schemafilter text, tbn text) OWNER TO postgres;

--
-- Name: 資料結構(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."資料結構"(cschema text, ctable text) RETURNS TABLE(field_name text, field_type text, field_len integer, field_dec integer, field_maxlen integer)
    LANGUAGE plpgsql
    AS $_$
begin
	return query 
	select
		column_name::Text field_name,
    	data_type::Text field_type,	
		coalesce(numeric_precision::integer,0) field_len,
		coalesce(numeric_scale::integer,0) field_dec,	
		coalesce(character_maximum_length::integer,0) field_maxlen
		
			from information_schema.columns 
				where table_schema = $1	and table_name = $2	order by ordinal_position;
end; 
$_$;


ALTER FUNCTION public."資料結構"(cschema text, ctable text) OWNER TO postgres;

--
-- Name: 資料結構同步(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."資料結構同步"(ctable1 text, ctable2 text, cschema text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2021/12/15 例如: select 資料結構同步('std','targe','public') */
    oRec record;
    /* 缺少之欄位 */
    t1 cursor for select aa.* from 資料結構($3,$1) aa  where aa.field_name not in (select bb.field_name from 資料結構($3,$2) bb );
    /* 相異之欄位  */
    t2 cursor for select aa.* from 資料結構($3,$1) aa,資料結構($3,$2) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    cSQL text;
begin
    --1.遇缺則補
    for oRec in t1 Loop    
        if  Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s add column %s %s(%s,%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
            --有長度數字
            cSQL = format('alter table %s add column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
            --有長度文字
            cSQL = format('alter Table %s add column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
            --只有型態
            cSQL = format('alter Table %s add column %s %s',$2,oRec.field_name,oRec.field_type) ;
        end if ;   
        --預設值        
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行        
        execute cSQL;
        
   end loop ;
   
    --2.相異則改  
    for oRec in t2 loop
        if Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s alter column %s %s(%s,%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	                        
        elsif Not oRec.field_len = 0 then
            --有長度
            cSQL = format('alter Table %s alter column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_len) ;
        elsif Not oRec.field_maxlen = 0 then
            --有長度
            cSQL = format('alter Table %s alter column %s %s(%s)',$2,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;            
        else     
            --只有型態
            cSQL = format('alter table %s alter column %s %s',$2,oRec.field_name,oRec.field_type) ;	
        end if ;   
        --預設值        
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行        
        execute cSQL;
    end loop;
     
end; 
$_$;


ALTER FUNCTION public."資料結構同步"(ctable1 text, ctable2 text, cschema text) OWNER TO postgres;

--
-- Name: 資料結構同步(text, text, text, text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public."資料結構同步"(IN cschema_std text, IN ctable_std text, IN cschema_targe text, IN ctable_targe text)
    LANGUAGE plpgsql
    AS $_$
declare
    /* By Fred 2023/05/15 */	
	/* 1.用法: call public."資料結構同步"(...) --可省略public */    
	/* 2.依賴函數 public."資料結構"(...) --可省略public */	
    /* 3.可公用者 應置於 public 區 */	
    oRec record;
    /* 缺少之欄位 */
    t1 cursor for select aa.* from "資料結構"($1,$2) aa  where aa.field_name not in (select bb.field_name from "資料結構"($3,$4) bb );
    /* 相異之欄位  */
    t2 cursor for select aa.* from "資料結構"($1,$2) aa, "資料結構"($3,$4) bb where aa.field_name=bb.field_name and ( aa.field_type<>bb.field_type or aa.field_len<>bb.field_len or aa.field_dec<>bb.field_dec) ;        
    cSQL text;
begin
    --1.遇缺則補
    for oRec in t1 Loop    
	    if oRec.field_type='integer' then 
			--整數		
			cSQL = format('alter Table %s."%s" add column "%s" %s',$3,$4,oRec.field_name,oRec.field_type) ;
        elseif  Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s."%s" add column "%s" %s(%s,%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	
        elsif Not oRec.field_len=0 then
            --有長度數字
            cSQL = format('alter table %s."%s" add column "%s" %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len) ;	
        elsif Not oRec.field_maxlen=0 then
            --有長度文字
            cSQL = format('alter Table %s."%s" add column "%s" %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;
        else
            --只有型態
            cSQL = format('alter Table %s."%s" add column "%s" %s',$3,$4,oRec.field_name,oRec.field_type) ;
        end if ;   
        --預設值        
        if oRec.field_type='text' or oRec.field_type='character' or oRec.field_type='character varying'then
            cSQL = cSQL||$$ not null default '' $$;
        elsif oRec.field_type='numeric' or oRec.field_type='integer' or oRec.field_type='real' then 
            cSQL = cSQL||$$ not null default 0 $$;
        end if ;
        --執行        
        execute cSQL;
        
   end loop ;
   
    --2.相異則改  
    for oRec in t2 loop
        if Not oRec.field_dec = 0 then
            --有小數
            cSQL = format('alter table %s."%s" alter column "%s" type %s(%s,%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len,oRec.field_dec) ;	                        
        elsif Not oRec.field_len = 0 then
            --有長度
            cSQL = format('alter Table %s."%s" alter column "%s" type %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_len) ;
        elsif Not oRec.field_maxlen = 0 then
            --有長度
            cSQL = format('alter Table %s."%s" alter column "%s" type %s(%s)',$3,$4,oRec.field_name,oRec.field_type,oRec.field_maxlen) ;            
        else     
            --只有型態
            cSQL = format('alter table %s."%s" alter column "%s" type %s',$3,$4,oRec.field_name,oRec.field_type) ;	
        end if ;           
        --執行        
        execute cSQL;
    end loop;
     
end; 
$_$;


ALTER PROCEDURE public."資料結構同步"(IN cschema_std text, IN ctable_std text, IN cschema_targe text, IN ctable_targe text) OWNER TO postgres;

--
-- Name: 資料結構差異數(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public."資料結構差異數"(ctable1 text, ctable2 text, cschema text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	nCount integer;
begin 
	-- t1=>source t2=>targe
	select count(1) from 資料結構($3,$1) t1 
		left join 資料結構($3,$2) t2 on (
			t1.field_name = t2.field_name and t1.field_type = t2.field_type and t1.field_len  = t2.field_len  and 
			t1.field_dec  = t2.field_dec  and t1.field_maxlen=t2.field_maxlen) 
		where t2.* is null 
		into nCount;
	
	return nCount;
end; 
$_$;


